import click
from http_client import request

@click.group()
@click.option('--verbose', is_flag=True)
def cli(verbose):
    request.verbose = verbose

@cli.command()
@click.argument('url')
def get(url):
    print(request('GET', url).text)

@cli.command()
@click.argument('url')
@click.argument('body')
def post(url, body):
    print(request('POST', url, data=body).text)

if __name__ == '__main__':
    cli()

